ceiling = 100000000;
const endpointBits = P.map((_, i) =>
  G.filter(([u]) => u === i).reduce((bits, [, , bit]) => bits | bit, 0n)
);
const directions = [[0n,1n],[1n,17n],[1n,0n],[1n,4n],[2n,5n],[1n,9n],[3n,17n],[1n,1n],[19n,28n],[1n,30n],[3n,77n],[3n,40n],[3n,1n],[3n,38n],[3n,53n],[2n,73n],[1n,11n]];
const groups = directions.map(([T,U]) => P
  .flatMap(([t,b,d], id) => {
    if (id === 24 || T*b !== U*t) return [];
    const r = T ? t/T : b/U;
    if (r <= 0n || t !== r*T || b !== r*U || d < 0n) throw Error("invalid ordinate");
    // e=-y-66z, f=(x+y+35z)/17, c=z.
    return [{id, r, d, threshold: [-U*d*r, (17n*T-U)*d*r, -17n*d*d+(1122n*T-35n*U)*d*r, 17n*r*r]}];
  })
  .sort((a,b) => sg(a.d*b.r-b.d*a.r))
